-- Retain the genuine new row under the original native XID/PID frame before
-- deriving its flags. The same existing segment writer runs after EVERY
-- observed request recompute; its actual post-write row is what is hashed.
update private.weekly_source_agency_timesheet_change_requests set current_financial_id=f.id,
 version=version+1,updated_at_utc=transaction_timestamp() where id=r.id returning * into r;
segment_flags_receipt:=private.weekly_source_agency_segment_flags_apply_v1(r.id);
select * into strict f from public.timesheets_financials where id=r.current_financial_id and is_current;
observation:=jsonb_build_object('schema_version','WEEKLY_SOURCE_AGENCY_NATIVE_FINANCIAL_WRITE_V1',

PERFORM private.weekly_source_agency_financial_write_observe_v1(
  p_timesheet_id,snap,null::uuid);
IF v_agency_write_purpose IS NOT NULL THEN
  SELECT tf.* INTO STRICT inserted_row FROM public.timesheets_financials tf
    WHERE tf.id=inserted_row.id AND tf.is_current;
END IF;
